{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Absolute oral bioavailability of the 1500 mg GSK1322322 free base tablet was 77% after a meal in healthy volunteers, supporting high oral bioavailability for a related aminopyrimidine-piperazine aniline drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "The same GSK1322322 tablet had 57% absolute oral bioavailability in the fasted state, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid showed 100% absolute oral bioavailability at an oral dose of 375 mg, demonstrating that small-molecule oral drugs with similar polar functionality can achieve complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone extended-release, a formulation with deliberately reduced absorption, still has 28% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Rifapentine has 70% absolute oral bioavailability after a single 600 mg dose in healthy volunteers, supporting high F for a lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Ketanserin absolute oral bioavailability was 46.8 ± 8.2% after a 20 mg oral dose in healthy male subjects, a moderate value still clearly above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus, despite incomplete absorption, has oral bioavailability of approximately 20–25%, meeting the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Apalutamide has approximately 100% absolute oral bioavailability determined by oral versus intravenous microtracer administration, supporting high F for a heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Venadaparib demonstrated good oral bioavailability with rapid absorption and dose-proportional exposure, supporting high F for a heteroaromatic small-molecule drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Praziquantel bioavailability was 27.2 ± 5.4% even in patients with hepatic disease, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small-molecule heteroaromatic oral drug with a piperazine-pyridine aniline and cyclopentyl substituent; all transferable experimental evidence points to absolute oral bioavailability at or above 20%, with most analogs showing 28–100% F. No affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific human pharmacokinetic or IV-comparator data are available.",
    "Structural analogs are not identical, so formulation and solubility effects on F are uncertain.",
    "No evidence addresses potential first-pass metabolism or transporter-limited absorption for this exact scaffold."
